public RenderSpecial(ItemStack stack) {
        this.theThingToRender = stack;
    }

public void render(EntityPlayer player, float partialTicks) {
        if (player.isInvisible() || !player.isWearing(EnumPlayerModelParts.CAPE) || player.isElytraFlying()) { return; }

        GlStateManager.pushMatrix();

        Vec3d currentPos = Minecraft.getMinecraft().player.getPositionEyes(partialTicks);
        Vec3d playerPos = player.getPositionEyes(partialTicks);
        GlStateManager.translate(playerPos.x - currentPos.x, playerPos.y - currentPos.y, playerPos.z - currentPos.z);
        GlStateManager.translate(0D, 2.575D - (player.isSneaking() ? 0.125D : 0D), 0D);

        this.render();
        GlStateManager.popMatrix();
    }

public void render() {
        if (StackUtil.isValid(this.theThingToRender)) {
            boolean isBlock = this.theThingToRender.getItem() instanceof ItemBlock;

            GlStateManager.pushMatrix();

            if (isBlock) {
                GlStateManager.translate(0D, -0.1875D, 0D);
            }
            GlStateManager.rotate(180F, 1.0F, 0.0F, 1.0F);

            float size = isBlock ? 0.5F : 0.4F;
            GlStateManager.scale(size, size, size);

            //Make the floaty stuff look nice using sine waves \o/ -xdjackiexd
            //Peck edit: What do you mean by "nice" you jackass? >_>
            double boop = Minecraft.getSystemTime() / 1000D;
            GlStateManager.translate(0D, Math.sin(boop % (2 * Math.PI)) * 0.25, 0D);
            GlStateManager.rotate((float) (boop * 40D % 360), 0, 1, 0);

            GlStateManager.disableLighting();
            GlStateManager.pushMatrix();

            if (!isBlock) {
                GlStateManager.translate(0D, 0.5D, 0D);
            }
            GlStateManager.rotate(180F, 1F, 0F, 0F);
            AssetUtil.renderItemInWorld(this.theThingToRender);
            GlStateManager.popMatrix();

            GlStateManager.enableLighting();

            GlStateManager.popMatrix();
        }
    }

public SpecialRenderInit() {
        new ThreadSpecialFetcher();
        MinecraftForge.EVENT_BUS.register(this);
    }

public static void parse(Properties properties) {
        for (String key : properties.stringPropertyNames()) {
            String[] values = properties.getProperty(key).split("@");
            if (values.length > 0) {
                String itemName = values[0];

                int meta;
                try {
                    meta = Integer.parseInt(values[1]);
                } catch (Exception e) {
                    meta = 0;
                }

                ResourceLocation resLoc = new ResourceLocation(itemName);
                ItemStack stack = findItem(resLoc, meta);

                //TODO Remove this block once the transition to 1.11 is done and the special people stuff file has been converted to snake_case
                if (!StackUtil.isValid(stack)) {
                    String convertedItemName = "";
                    for (char c : itemName.toCharArray()) {
                        if (Character.isUpperCase(c)) {
                            convertedItemName += "_";
                            convertedItemName += Character.toLowerCase(c);
                        } else {
                            convertedItemName += c;
                        }
                    }
                    stack = findItem(new ResourceLocation(convertedItemName), meta);
                }

                if (StackUtil.isValid(stack)) {
                    SPECIAL_LIST.put(key.toLowerCase(Locale.ROOT), new RenderSpecial(stack));
                }
            }
        }
    }

private static ItemStack findItem(ResourceLocation resLoc, int meta) {
        if (Item.REGISTRY.containsKey(resLoc)) {
            Item item = Item.REGISTRY.getObject(resLoc);
            if (item != null) { return new ItemStack(item, 1, meta); }
        } else if (Block.REGISTRY.containsKey(resLoc)) {
            Block block = Block.REGISTRY.getObject(resLoc);
            if (block != null) { return new ItemStack(block, 1, meta); }
        }
        return StackUtil.getEmpty();
    }

@SubscribeEvent(priority = EventPriority.HIGHEST)
    public void onPlayerRender(RenderPlayerEvent.Pre event) {
        if (event.getEntityPlayer() != null) {
            String name = event.getEntityPlayer().getName();
            if (name != null) {
                String lower = name.toLowerCase(Locale.ROOT);
                if (SPECIAL_LIST.containsKey(lower)) {
                    RenderSpecial render = SPECIAL_LIST.get(lower);
                    if (render != null) {
                        render.render(event.getEntityPlayer(), event.getPartialRenderTick());
                    }
                }
            }
        }
    }

public ThreadSpecialFetcher() {
        this.setName(ActuallyAdditions.NAME + " Special Fetcher");
        this.setDaemon(true);
        this.start();
    }

@Override
    public void run() {
        ActuallyAdditions.LOGGER.info("Fetching Special People Stuff...");
        try {
            URL url = new URL("https://raw.githubusercontent.com/Ellpeck/ActuallyAdditions/main/specialPeopleStuff.properties");
            Properties specialProperties = new Properties();
            specialProperties.load(new InputStreamReader(url.openStream()));
            SpecialRenderInit.parse(specialProperties);

            ActuallyAdditions.LOGGER.info("Fetching Special People Stuff done!");
        } catch (Exception e) {
            ActuallyAdditions.LOGGER.error("Fetching Special People Stuff failed! (You can ignore this error technically.)", e);
        }
    }

public PacketClientToServer(NBTTagCompound data, IDataHandler handler) {
        this.data = data;
        this.handler = handler;
    }

@Override
    public void fromBytes(ByteBuf buf) {
        PacketBuffer buffer = new PacketBuffer(buf);
        try {
            this.data = buffer.readCompoundTag();

            int handlerId = buffer.readInt();
            if (handlerId >= 0 && handlerId < PacketHandler.DATA_HANDLERS.size()) {
                this.handler = PacketHandler.DATA_HANDLERS.get(handlerId);
            }
        } catch (Exception e) {
            ActuallyAdditions.LOGGER.error("Something went wrong trying to receive a server packet!", e);
        }
    }

@Override
    public void toBytes(ByteBuf buf) {
        PacketBuffer buffer = new PacketBuffer(buf);

        buffer.writeCompoundTag(this.data);
        buffer.writeInt(PacketHandler.DATA_HANDLERS.indexOf(this.handler));
    }

@Override
        public IMessage onMessage(final PacketClientToServer message, final MessageContext ctx) {
            FMLCommonHandler.instance().getMinecraftServerInstance().addScheduledTask(() -> {
                if (message.data != null && message.handler != null) {
                    message.handler.handleData(message.data, ctx);
                }
            });
            return null;
        }

@Override
